 4	public class HuffmanCodingTest {
 5	    public static void main(String[] args) {
 6	        shouldGenerateExpectedTraversalOrderCodes();
 7	        shouldGenerateExpectedSymbolOrderCodes();
 8	        shouldHandleSingleSymbol();
 9	        shouldHandleEmptyInput();
10	        shouldRejectNullFrequencies();
11	        shouldRejectNegativeFrequencies();
12	        shouldRejectMismatchedInputLengths();
13	    }
