31	    private static void shouldHandleSingleSymbol() {
32	        assertListEquals(
33	                Arrays.asList("0"),
34	                HuffmanCoding.huffmanCodes(new int[]{7}),
35	                "single symbol should be encoded as 0"
36	        );
37	    }
