63	    private static void shouldRejectNegativeFrequencies() {
64	        assertThrows(
65	                IllegalArgumentException.class,
66	                () -> HuffmanCoding.huffmanCodes(new int[]{2, -1, 3}),
67	                "negative frequencies should be rejected"
68	        );
69	    }
