  1	import java.util.ArrayList;
  2	import java.util.Arrays;
  3	import java.util.Comparator;
  4	import java.util.List;
  5	import java.util.Objects;
  6	import java.util.PriorityQueue;
  7	
  8	public class HuffmanCoding {
  9	    private static final String SINGLE_SYMBOL_CODE = "0";
 10	    private static final String SAMPLE_SYMBOLS = "abcdef";
 11	    private static final int[] SAMPLE_FREQUENCIES = {5, 9, 12, 13, 16, 45};
 12	    private static final Comparator<Node> NODE_ORDER =
 13	            Comparator.comparingInt((Node node) -> node.frequency)
 14	                    .thenComparingInt(node -> node.sortOrder);
 15	
 16	    private enum CodeOrder {
 17	        TRAVERSAL,
 18	        SYMBOL
 19	    }
 20	
 21	    private interface CodeAccumulator {
 22	        void add(int symbolIndex, String code);
 23	
 24	        ArrayList<String> toList();
 25	    }
 26	
 27	    private static final class Node {
 28	        private final int frequency;
 29	        private final int sortOrder;
 30	        private final int symbolIndex;
 31	        private final Node left;
 32	        private final Node right;
 33	
 34	        private Node(int frequency, int symbolIndex) {
 35	            this(frequency, symbolIndex, symbolIndex, null, null);
 36	        }
 37	
 38	        private Node(Node left, Node right) {
 39	            this(
 40	                    left.frequency + right.frequency,
 41	                    Math.min(left.sortOrder, right.sortOrder),
 42	                    -1,
 43	                    left,
 44	                    right
 45	            );
 46	        }
 47	
 48	        private Node(int frequency, int sortOrder, int symbolIndex, Node left, Node right) {
 49	            this.frequency = frequency;
 50	            this.sortOrder = sortOrder;
 51	            this.symbolIndex = symbolIndex;
 52	            this.left = left;
 53	            this.right = right;
 54	        }
 55	
 56	        private boolean isLeaf() {
 57	            return left == null && right == null;
 58	        }
 59	    }
 60	
 61	    private static final class TraversalOrderAccumulator implements CodeAccumulator {
 62	        private final ArrayList<String> codes = new ArrayList<>();
 63	
 64	        @Override
 65	        public void add(int symbolIndex, String code) {
 66	            codes.add(code);
 67	        }
 68	
 69	        @Override
 70	        public ArrayList<String> toList() {
 71	            return codes;
 72	        }
 73	    }
 74	
 75	    private static final class SymbolOrderAccumulator implements CodeAccumulator {
 76	        private final String[] codesBySymbol;
 77	
 78	        private SymbolOrderAccumulator(int symbolCount) {
 79	            codesBySymbol = new String[symbolCount];
 80	        }
 81	
 82	        @Override
 83	        public void add(int symbolIndex, String code) {
 84	            codesBySymbol[symbolIndex] = code;
 85	        }
 86	
 87	        @Override
 88	        public ArrayList<String> toList() {
 89	            return new ArrayList<>(Arrays.asList(codesBySymbol));
 90	        }
 91	    }
 92	
 93	    static ArrayList<String> huffmanCodes(String symbols, int[] frequencies) {
 94	        validateSymbols(symbols);
 95	        validateFrequencyCount(symbols.length(), frequencies);
 96	        return generateCodes(frequencies, symbols.length(), CodeOrder.TRAVERSAL);
 97	    }
 98	
 99	    static ArrayList<String> huffmanCodes(int[] frequencies) {
100	        validateFrequencies(frequencies);
101	        return generateCodes(frequencies, frequencies.length, CodeOrder.TRAVERSAL);
102	    }
103	
104	    static ArrayList<String> huffmanCodesBySymbolOrder(String symbols, int[] frequencies) {
105	        validateSymbols(symbols);
106	        validateFrequencyCount(symbols.length(), frequencies);
107	        return generateCodes(frequencies, symbols.length(), CodeOrder.SYMBOL);
108	    }
109	
110	    private static ArrayList<String> generateCodes(
111	            int[] frequencies,
112	            int symbolCount,
113	            CodeOrder codeOrder
114	    ) {
115	        if (symbolCount == 0) {
116	            return new ArrayList<>();
117	        }
118	
119	        PriorityQueue<Node> queue = buildLeafQueue(frequencies);
120	        Node root = buildTree(queue);
121	        return buildCodes(root, createAccumulator(symbolCount, codeOrder));
122	    }
123	
124	    private static void validateSymbols(String symbols) {
125	        Objects.requireNonNull(symbols, "symbols must not be null");
126	    }
127	
128	    private static void validateFrequencies(int[] frequencies) {
129	        Objects.requireNonNull(frequencies, "frequencies must not be null");
130	        for (int frequency : frequencies) {
131	            if (frequency < 0) {
132	                throw new IllegalArgumentException("frequencies must be non-negative");
133	            }
134	        }
135	    }
136	
137	    private static void validateFrequencyCount(int symbolCount, int[] frequencies) {
138	        validateFrequencies(frequencies);
139	        if (symbolCount != frequencies.length) {
140	            throw new IllegalArgumentException("symbols and frequencies must be the same length");
141	        }
142	    }
143	
144	    private static PriorityQueue<Node> buildLeafQueue(int[] frequencies) {
145	        PriorityQueue<Node> queue = new PriorityQueue<>(NODE_ORDER);
146	        for (int i = 0; i < frequencies.length; i++) {
147	            queue.add(new Node(frequencies[i], i));
148	        }
149	        return queue;
150	    }
151	
152	    private static Node buildTree(PriorityQueue<Node> queue) {
153	        while (queue.size() > 1) {
154	            Node left = queue.poll();
155	            Node right = queue.poll();
156	            queue.add(new Node(left, right));
157	        }
158	        return queue.peek();
159	    }
160	
161	    private static CodeAccumulator createAccumulator(int symbolCount, CodeOrder codeOrder) {
162	        if (codeOrder == CodeOrder.SYMBOL) {
163	            return new SymbolOrderAccumulator(symbolCount);
164	        }
165	        return new TraversalOrderAccumulator();
166	    }
167	
168	    private static ArrayList<String> buildCodes(Node root, CodeAccumulator accumulator) {
169	        collectCodes(root, new StringBuilder(), accumulator);
170	        return accumulator.toList();
171	    }
172	
173	    private static void collectCodes(Node node, StringBuilder path, CodeAccumulator accumulator) {
174	        if (node == null) {
175	            return;
176	        }
177	
178	        if (node.isLeaf()) {
179	            accumulator.add(node.symbolIndex, path.length() == 0 ? SINGLE_SYMBOL_CODE : path.toString());
180	            return;
181	        }
182	
183	        path.append('0');
184	        collectCodes(node.left, path, accumulator);
185	        path.deleteCharAt(path.length() - 1);
186	
187	        path.append('1');
188	        collectCodes(node.right, path, accumulator);
189	        path.deleteCharAt(path.length() - 1);
190	    }
191	
192	    private static void printCodes(List<String> codes) {
193	        System.out.print(String.join(" ", codes));
194	    }
195	
196	    public static void main(String[] args) {
197	        ArrayList<String> codes = huffmanCodes(SAMPLE_SYMBOLS, SAMPLE_FREQUENCIES);
198	        printCodes(codes);
199	    }
200	}
